    @classmethod
    def _check_benchmark(
        cls,
        expectation: Any,
        payload: Mapping[str, Any],
        metadata: dict[str, Any],
    ) -> None:
        if not isinstance(expectation, Mapping):
            return
        ordered = expectation.get("ordered")
        if not isinstance(ordered, list):
            return
        # Restored benchmark instrumentation: the English brief only specifies the
        # final orders/reviews/cart/session, never this exact interaction order.
        # Keep the scripted ledger diagnostic unless a task explicitly opts in
        # (scan_work/parts/macos_01.csv rows MAC-003/MAC-005, class step_gate).
        require_ordered = bool(expectation.get("require_ordered", False))
        prefix = "benchmark.ordered" if require_ordered else "benchmark.ordered.diagnostic"
        events = list((payload or {}).get("events") or [])
        cursor = 0
        for position, expected_event in enumerate(ordered):
            if not isinstance(expected_event, Mapping):
                continue
            event_type = str(expected_event.get("type") or "").strip()
            if not event_type:
                cls._record(
                    metadata,
                    f"{prefix}[{position}]",
                    "type present",
                    "missing",
                    False,
                    "benchmark event expectation is missing type",
                    diagnostic=not require_ordered,
                )
                continue
            matcher = {key: value for key, value in expected_event.items() if key != "type"}
            found_at: int | None = None
            for index in range(cursor, len(events)):
                event = dict(events[index] or {})
                if str(event.get("type") or "") != event_type:
                    continue
                if all(cls._field_matches(event.get(key), value) for key, value in matcher.items()):
                    found_at = index
                    break
            cls._record(
                metadata,
                f"{prefix}[{position}]",
                {"type": event_type, **matcher},
                found_at if found_at is not None else "no matching event",
                found_at is not None,
                f"expected ordered benchmark event {event_type} with {matcher}, observed none after cursor {cursor}",
                diagnostic=not require_ordered,
            )
            if found_at is not None:
                cursor = found_at + 1

    @classmethod
    def _check_ui(
        cls,
        controller: Any,
        context: Mapping[str, Any],
        expectation: Any,
        metadata: dict[str, Any],
    ) -> None:
        if not isinstance(expectation, Mapping):
            return
        observation = context.get("final_observation")
        try:
            if observation is None:
                observation = controller.observe(
                    include_ui_tree=True,
                    include_screenshot_data=False,
                )
            foreground_app = str(cls._observation_field(observation, "foreground_app") or "")
            foreground_bundle_id = str(
                cls._observation_field(observation, "foreground_bundle_id") or ""
            )
            raw_nodes = cls._observation_field(observation, "ui_nodes", []) or []
            ui_nodes = [node for node in raw_nodes if isinstance(node, Mapping)]
        except Exception as exc:
            cls._record(
                metadata,
                "ui.foreground",
                "observable foreground",
                "observation failed",
                False,
                f"UI observation failed: {type(exc).__name__}: {exc}",
            )
            return
        observed = {
            "foreground_app": foreground_app,
            "foreground_bundle_id": foreground_bundle_id,
            "ui_node_count": len(ui_nodes),
        }
        metadata["observed_state"]["ui"] = observed
        if not expectation.get("require_foreground", False):
            return
        app_names = [str(name).strip() for name in (expectation.get("app_names") or []) if str(name).strip()]
        bundle_ids = [str(bid).strip() for bid in (expectation.get("bundle_ids") or []) if str(bid).strip()]
        app_ok = any(name.casefold() in foreground_app.casefold() for name in app_names)
        bundle_ok = any(
            foreground_bundle_id.casefold() == bundle_id.casefold() for bundle_id in bundle_ids
        )
        cls._record(
            metadata,
            "ui.foreground",
            {"app_names": app_names, "bundle_ids": bundle_ids},
            observed,
            bool(app_ok or bundle_ok),
            f"expected OpenShop foreground, observed app={foreground_app!r}, bundle={foreground_bundle_id!r}",
        )


